// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title DAORegistry
 * @dev A central contract to store and manage the addresses of all other contracts in the ecosystem.
 * This acts as the single source of truth for the dApp.
 */
contract DAORegistry is Ownable {
    mapping(bytes32 => address) private addresses;

    event AddressSet(bytes32 indexed key, address newAddress);

    // --- Pre-defined keys for contracts ---
    bytes32 public constant RAYAN_CHAIN_DAO = keccak256("RAYAN_CHAIN_DAO");
    bytes32 public constant RAYAN_CHAIN_TOKEN = keccak256("RAYAN_CHAIN_TOKEN");
    bytes32 public constant FINANCE = keccak256("FINANCE");
    bytes32 public constant STAKING = keccak256("STAKING");
    bytes32 public constant ACC_CONTROL = keccak256("ACC_CONTROL");
    bytes32 public constant USER_PROFILE = keccak256("USER_PROFILE");

    constructor(address initialOwner) Ownable(initialOwner) {}

    /**
     * @notice Sets or updates the address for a given contract key.
     * @dev Can only be called by the owner.
     * @param _key The identifier for the contract (e.g., keccak256("FINANCE")).
     * @param _address The new address of the contract.
     */
    function setAddress(bytes32 _key, address _address) external onlyOwner {
        require(_address != address(0), "Registry: Zero address is not allowed");
        addresses[_key] = _address;
        emit AddressSet(_key, _address);
    }

    /**
     * @notice Retrieves the address for a given contract key.
     * @param _key The identifier for the contract.
     * @return The stored address.
     */
    function getAddress(bytes32 _key) external view returns (address) {
        return addresses[_key];
    }
}

src/contracts/Finance.sol.content:
// src/contracts/Finance.sol - اصلاح شده برای مالکیت Timelock
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol"; // ❌ Keep Ownable but change usage
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interfaces/IFinance.sol";
import "./permission/AccControl.sol"; // ✅ NEW: Import AccControl

/**
 * @title Finance Contract (Treasury) - Professional Version
 * @dev Manages DAO funds with support for milestone-based investments and platform fees.
 * This contract acts as the intelligent vault for a VC DAO.
 * Ownership is handled by the Timelock/DAO via the EXECUTOR_ROLE.
 */
contract Finance is IFinance, Ownable, ReentrancyGuard { // Keep Ownable for setDaoAddress, but change core logic
    IERC20 public immutable token;
    address public daoAddress;
    AccControl public accControl; // ✅ NEW: State variable for AccControl

    // Platform fee in basis points (e.g., 250 = 2.5%)
    uint256 public platformFeeBps; // Bps = Basis Points. 1% = 100 Bps.

    // Struct to hold all details of an investment tied to a proposal
    struct Investment {
        address recipient;
        uint256 totalAmount;
        uint256 releasedAmount;
        uint8 milestoneCount;
        uint8 currentMilestone;
        bool isActive;
    }

    // Mapping from proposal ID to its investment details
    mapping(uint256 => Investment) public investments;

    constructor(address _initialOwner, address _tokenAddress, uint256 _platformFeeBps, address _accControlAddress) 
        Ownable(_initialOwner) {
        require(_initialOwner != address(0), "Owner cannot be zero address");
        require(_tokenAddress != address(0), "Token cannot be zero address");
        require(_platformFeeBps <= 1000, "Fee cannot exceed 10%"); // Safety check: max 10% fee
        token = IERC20(_tokenAddress);
        platformFeeBps = _platformFeeBps;
        accControl = AccControl(_accControlAddress); // ✅ NEW: Set AccControl
    }

    // --- Modifiers ---
    // ✅ NEW MODIFIER: برای عملیات‌های حساس که باید توسط Timelock/DAO انجام شوند
    modifier onlyExecutor() {
        require(accControl.hasRole(accControl.EXECUTOR_ROLE(), msg.sender), "Finance: Must be Executor Role");
        _;
    }

    /**
     * @dev Allows anyone to deposit native currency (e.g., ETH, MATIC) into the treasury.
     */
    receive() external payable {
        emit FundsDeposited(msg.sender, msg.value);
    }

    // --- Core Investment Logic ---

    /**
     * @notice Registers a new investment when a proposal passes. Called by the main DAO contract (via Timelock).
     */
    function registerInvestment(uint256 _proposalId, address _recipient, uint256 _totalAmount, uint8 _milestoneCount) external override onlyExecutor { // ✅ CHANGE: Replaced onlyOwner with onlyExecutor
        require(_recipient != address(0), "Recipient cannot be zero address");
        require(_totalAmount > 0, "Total amount must be greater than zero");
        require(_milestoneCount > 0, "Must have at least one milestone");
        require(!investments[_proposalId].isActive, "Investment for this proposal already exists");

        investments[_proposalId] = Investment({
            recipient: _recipient,
            totalAmount: _totalAmount,
            releasedAmount: 0,
            milestoneCount: _milestoneCount,
            currentMilestone: 0,
            isActive: true
        });

        emit InvestmentRegistered(_proposalId, _recipient, _totalAmount, _milestoneCount);
    }

    /**
     * @notice Releases the funds for the next milestone of a project. Called by the main DAO contract (via Timelock).
     */
    function releaseNextMilestone(uint256 _proposalId) external nonReentrant onlyExecutor { // ✅ CHANGE: Replaced onlyOwner with onlyExecutor
        Investment storage investment = investments[_proposalId];
        require(investment.isActive, "Investment is not active");
        require(investment.currentMilestone < investment.milestoneCount, "All milestones have been released");

        uint256 milestoneAmount = investment.totalAmount / investment.milestoneCount;
        // Note: A more complex implementation could handle potential remainder dust from division.

        uint256 feeAmount = (milestoneAmount * platformFeeBps) / 10000;
        uint256 amountToRecipient = milestoneAmount - feeAmount;

        require(token.balanceOf(address(this)) >= milestoneAmount, "Finance: Insufficient funds for this milestone");

        if (feeAmount > 0) {
            emit PlatformFeeTaken(_proposalId, feeAmount);
        }

        bool success = token.transfer(investment.recipient, amountToRecipient);
        require(success, "Finance: Token transfer to recipient failed");

        investment.releasedAmount += milestoneAmount;
        investment.currentMilestone++;

        if (investment.currentMilestone == investment.milestoneCount) {
            investment.isActive = false;
        }

        emit MilestoneReleased(_proposalId, amountToRecipient, investment.currentMilestone);
    }


    /**
     * @notice This function is deprecated for new investments but is kept for IFinance compatibility.
     * Use releaseNextMilestone for new, structured investments.
     */
    function releaseFunds(address payable, uint256) external view override onlyOwner { // Keep onlyOwner for access control to deprecated function
        revert("Finance: This function is deprecated. Use releaseNextMilestone instead.");
    }

    /**
     * @notice Withdraws native currency from the treasury. Called by the DAO (via Timelock) for operational purposes.
     */
    function withdraw(address payable to, uint256 amount) external override onlyExecutor nonReentrant { // ✅ CHANGE: Replaced onlyOwner with onlyExecutor
        require(address(this).balance >= amount, "Finance: Insufficient native balance");
        (bool success, ) = to.call{value: amount}("");
        require(success, "Finance: Native currency transfer failed");
        emit NativeFundsWithdrawn(to, amount);
    }

    /**
     * @notice Withdraws RYC tokens from the treasury. Called by the DAO (via Timelock) for operational purposes.
     */
    function withdrawTokens(address to, uint256 amount) external override onlyExecutor nonReentrant { // ✅ CHANGE: Replaced onlyOwner with onlyExecutor
        require(token.balanceOf(address(this)) >= amount, "Finance: Insufficient RYC funds");
        bool success = token.transfer(to, amount);
        require(success, "Finance: RYC token transfer failed");
        emit TokenFundsWithdrawn(to, amount);
    }

    // --- Configuration Functions ---

    /**
     * @notice Sets the DAO contract address. Can only be called by the current owner.
     * @dev This remains onlyOwner since changing the DAO address is a highly sensitive admin function 
     *      that will be executed by the Timelock (which will be the owner).
     */
    function setDaoAddress(address _daoAddress) external override onlyOwner { 
        require(_daoAddress != address(0), "Finance: DAO address cannot be zero");
        daoAddress = _daoAddress;
        emit DaoAddressSet(_daoAddress);
    }
}

src/contracts/interfaces/IFinance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title IFinance Interface
 * @dev Defines the external functions and events for the Finance (Treasury) contract.
 * This ensures that other contracts, like the main DAO, can interact with it in a typed and secure way.
 */
interface IFinance {
    // --- Events from the original design ---
    event FundsDeposited(address indexed from, uint256 amount);
    event FundsReleased(address indexed recipient, uint256 amount);
    event NativeFundsWithdrawn(address indexed to, uint256 amount);
    event TokenFundsWithdrawn(address indexed to, uint256 amount);

    // ✅✅✅ رویدادهای جدید برای پشتیبانی از سرمایه‌گذاری فازبندی شده ✅✅✅
    event InvestmentRegistered(uint256 indexed proposalId, address indexed recipient, uint256 totalAmount, uint8 milestoneCount);
    event MilestoneReleased(uint256 indexed proposalId, uint256 amount, uint8 milestoneNumber);
    event PlatformFeeTaken(uint256 indexed proposalId, uint256 feeAmount);
    event InvestmentCancelled(uint256 indexed proposalId);
    event DaoAddressSet(address indexed newDaoAddress);

    // --- Functions from the original design ---
    function releaseFunds(address payable recipient, uint256 amount) external view;
    function withdraw(address payable to, uint256 amount) external;
    function withdrawTokens(address to, uint256 amount) external;

    // ✅✅✅ توابع جدید برای پشتیبانی از سرمایه‌گذاری فازبندی شده ✅✅✅
    function registerInvestment(uint256 _proposalId, address _recipient, uint256 _totalAmount, uint8 _milestoneCount) external;
    function releaseNextMilestone(uint256 _proposalId) external;

    // ✅✅✅ توابع جدید مدیریتی ✅✅✅
    function setDaoAddress(address _daoAddress) external;

    // ✅✅✅ توابع view برای خواندن اطلاعات از خارج قرارداد (اختیاری اما بسیار مفید) ✅✅✅
    function investments(uint256 proposalId) external view returns (
        address recipient,
        uint256 totalAmount,
        uint256 releasedAmount,
        uint8 milestoneCount,
        uint8 currentMilestone,
        bool isActive
    );

    function platformFeeBps() external view returns (uint256);

    function daoAddress() external view returns (address);
}

